// Package schema is verse's self-description: every tony signature the runtime's own types
// generate, indexed by name and served over HTTP so the API can be read as data rather than
// as prose.
//
// It is an INDEX, not a source. The signatures live with the packages that declare the types
// (api.Schema, trigger.Schema, …), generated by tony-codegen from the Go structs, so they
// cannot drift from the code. This package only gathers and names them.
//
// The one exception is curated.tony, for types codegen cannot describe correctly today. Those
// are reported separately — see Curated — because a curated signature CAN drift from the code
// and a generated one cannot, and a reader deserves to know which kind they are looking at.
package schema

import (
	_ "embed"
	"fmt"
	"sort"
	"sync"

	"github.com/signadot/tony-format/go-tony/ir"

	"github.com/signadot/verse/api"
	"github.com/signadot/verse/codec"
	"github.com/signadot/verse/config"
	"github.com/signadot/verse/launch"
	"github.com/signadot/verse/process"
	"github.com/signadot/verse/trigger"
)

//go:embed curated.tony
var curatedDoc []byte

// A signature document is a tony object carrying `define` (the field types) and `signature`
// (its name). The name is how everything else refers to it, so it is the index key.
const (
	sigField  = "signature"
	nameField = "name"
)

var (
	once     sync.Once
	byName   map[string]*ir.Node
	curated  map[string]bool
	loadErr  error
	sortedNm []string
)

// load parses every embedded document once. A malformed embedded schema is a build-time
// mistake surfaced at first use rather than a panic at init: the endpoint reports it, and the
// rest of the server keeps serving.
func load() {
	byName = map[string]*ir.Node{}
	curated = map[string]bool{}

	// Generated first, so a curated entry for a type codegen has since learned to describe
	// is overridden by the real thing rather than shadowing it.
	for _, src := range [][]byte{api.Schema, trigger.Schema, process.Schema, config.Schema, launch.Schema} {
		if err := index(src, false); err != nil {
			loadErr = err
			return
		}
	}
	if err := index(curatedDoc, true); err != nil {
		loadErr = err
		return
	}
	for n := range byName {
		sortedNm = append(sortedNm, n)
	}
	sort.Strings(sortedNm)
}

// index parses a multi-document tony file and files each signature under its name.
func index(src []byte, isCurated bool) error {
	docs, err := codec.ParseNodes(src, codec.Tony)
	if err != nil {
		return fmt.Errorf("parse schema: %w", err)
	}
	for _, d := range docs {
		name := signatureName(d)
		if name == "" {
			continue // a document with no signature name indexes under nothing
		}
		if isCurated {
			// Prefer the derived truth — but only where there IS one. A generated signature
			// with an empty `define` is not a description, it is an absence: that is what
			// codegen emits for a type with a hand-written codec (trigger.Match, whose
			// grammar is the most-authored thing in the system). Letting that shadow a
			// curated entry would publish the emptiest possible claim about the type people
			// most need described. When codegen learns to describe it, its `define` stops
			// being empty and it takes over here with no edit.
			if prev, generated := byName[name]; generated && described(prev) {
				continue
			}
			curated[name] = true
		}
		byName[name] = d
	}
	return nil
}

// described reports whether a signature document actually says anything about its type —
// i.e. whether its `define` has any fields. codegen emits `define: {}` for a type it cannot
// describe, and an empty define published as a schema claims the type has no shape at all,
// which is a stronger and falser statement than saying nothing.
func described(d *ir.Node) bool {
	if d == nil || d.Type != ir.ObjectType {
		return false
	}
	def := ir.Get(d, "define")
	return def != nil && def.Type == ir.ObjectType && len(def.Fields) > 0
}

// signatureName reads `signature.name` from a signature document.
func signatureName(d *ir.Node) string {
	if d == nil || d.Type != ir.ObjectType {
		return ""
	}
	sig := ir.Get(d, sigField)
	if sig == nil || sig.Type != ir.ObjectType {
		return ""
	}
	n := ir.Get(sig, nameField)
	if n == nil || n.Type != ir.StringType {
		return ""
	}
	return n.String
}

// Names lists every signature, sorted.
func Names() ([]string, error) {
	once.Do(load)
	return sortedNm, loadErr
}

// Get returns one signature document by name.
func Get(name string) (*ir.Node, bool, error) {
	once.Do(load)
	if loadErr != nil {
		return nil, false, loadErr
	}
	d, ok := byName[name]
	return d, ok, nil
}

// Curated reports the names whose signature is hand-written rather than generated — the part
// of the published schema that is a claim about the code rather than a product of it.
func Curated() ([]string, error) {
	once.Do(load)
	if loadErr != nil {
		return nil, loadErr
	}
	out := make([]string, 0, len(curated))
	for n := range curated {
		out = append(out, n)
	}
	sort.Strings(out)
	return out, nil
}

// All returns the whole graph as one document: every signature under its name, plus the
// curated list so the two kinds stay distinguishable in a single response.
func All() (*ir.Node, error) {
	once.Do(load)
	if loadErr != nil {
		return nil, loadErr
	}
	sigs := make(map[string]*ir.Node, len(byName))
	for n, d := range byName {
		sigs[n] = d.DeepCopy() // parented into a new document; never hand out the index's node
	}
	cur, _ := Curated()
	curNodes := make([]*ir.Node, 0, len(cur))
	for _, n := range cur {
		curNodes = append(curNodes, ir.FromString(n))
	}
	return ir.FromMap(map[string]*ir.Node{
		"signatures": ir.FromMap(sigs),
		"curated":    ir.FromSlice(curNodes),
	}), nil
}
